// PICAXE BASIC compiler for the code generated by the PICAXE blocks: BASIC text -> program images for picaxeUploader.js.
// Only the 28X2 (AutoProgX2) is supported. The format was reverse-engineered from the official compiler output
// (picaxe28x2 -o), the test file checks byte-identical images on programs compiled by the official compiler.
//
// Program memory (obj, 4096 bytes): bits 0..23 = header ((end bit + 1) << 1 | class bit of the first statement),
// then from bit 24 a MSB-first bit stream: statement body, class bit of the next statement, next body, ...,
// terminator "11111". Each opcode starts with a lead bit, written before the body (1 for end, servo, hi2cout and the
// terminator). A jump address (15 bits) is the absolute bit position of the lead bit of its target. After the terminator, when gosub is used: 16 zero bits then the
// 15-bit return address of each gosub (gosub n = n-th gosub of the program).
// program() gives the instructions executed by picaxeMachine.js (simulator), built from the same items as the bit stream.

const PICAXE_COMPILER = {
    CHIPS: ['28X2'],
    OBJ_SIZE: 4096,
    PROGRAM_SIZE: 3840, // 3840..4095: table
    EEPROM_SIZE: 256,
    OPS: { '+': 0b00011, '-': 0b00010, '*': 0b00100, '/': 0b00111, '//': 0b00110, '&': 0b01001, '|': 0b01011 },
    // jump when the condition is false (if, do while)
    CMP_FALSE: { '=': 0b00011, '<>': 0b00100, '<': 0b00110, '<=': 0b00010, '>': 0b00101, '>=': 0b00001 },
    NEGATE: { '=': '<>', '<>': '=', '<': '>=', '>=': '<', '>': '<=', '<=': '>' },
    PORTS: { B: 0, C: 8, A: 16 },
    // 28X2 readadc channel of each pin
    ADC: {
        'A.0': 0, 'A.1': 1, 'A.2': 2, 'A.3': 3, 'B.0': 12, 'B.1': 10, 'B.2': 8, 'B.3': 9, 'B.4': 11, 'B.5': 13,
        'C.2': 14, 'C.3': 4, 'C.4': 16, 'C.5': 17, 'C.6': 18, 'C.7': 19
    },
    SERTXD: '10011110000101001010111'
};

class PicaxeCompileError extends Error {
    constructor(message, line) {
        super(line ? `line ${line}: ${message}` : message);
        this.line = line;
    }
}

const picaxeBits = (value, n) => value.toString(2).padStart(n, '0');

// unsigned number: 00 + 1 bit, 01 + 4 bits, 10 + 8 bits, 11 + 16 bits
function picaxeNumber(n) {
    if (n < 2) return '00' + n;
    if (n < 16) return '01' + picaxeBits(n, 4);
    if (n < 256) return '10' + picaxeBits(n, 8);
    return '11' + picaxeBits(n, 16);
}

class PicaxeCompiler {
    constructor(source) {
        this.source = source;
        this.symbols = Object.create(null);
        this.items = []; // { bits(addresses) => string, end: bool, line } or { label }
        this.blocks = []; // open if/do/for
        this.gosubs = 0;
        this.labelCount = 0;
    }

    static compile(source) {
        return new PicaxeCompiler(source).compile();
    }

    compile() {
        this.source.split(/\r?\n/).forEach((text, i) => this.line(text, i + 1));
        if (this.blocks.length) throw new PicaxeCompileError(`missing ${this.blocks.at(-1).type === 'if' ? 'endif' : this.blocks.at(-1).type === 'do' ? 'loop' : 'next'}`);
        return this.link();
    }

    // ---------- operands

    // variable slot: { byte, word } (b/w register) or { pin } (pinX.n)
    slot(name, line) {
        name = name.toLowerCase();
        if (name in this.symbols) name = this.symbols[name];
        let m = name.match(/^([bw])(\d+)$/);
        if (m) {
            const n = +m[2], byte = m[1] === 'w' ? 2 * n : n;
            if (byte > 55) throw new PicaxeCompileError(`unknown variable ${name}`, line);
            return { byte, word: m[1] === 'w' };
        }
        m = name.match(/^pin([abc])\.([0-7])$/);
        if (m) return { pin: PICAXE_COMPILER.PORTS[m[1].toUpperCase()] + +m[2] };
        throw new PicaxeCompileError(`unknown variable ${name}`, line);
    }

    variable(name, line) {
        const s = this.slot(name, line);
        return 'pin' in s ? s.pin : (Math.floor(s.byte / 14) << 6) | 0x20 | (2 + s.byte % 14) | (s.word ? 0x10 : 0);
    }

    isNumber(token) {
        return /^\d+$/.test(token);
    }

    // 124, %01111100 or $7C
    constant(token, line) {
        const m = token.match(/^(?:(\d+)|%([01]+)|\$([0-9a-f]+))$/i);
        if (!m) throw new PicaxeCompileError(`number expected: ${token}`, line);
        return m[1] ? +m[1] : parseInt(m[2] || m[3], m[2] ? 2 : 16);
    }

    // value operand: 1 + number, or 0 + variable code
    operand(token, line) {
        if (/^(\d+|%[01]+|\$[0-9a-f]+)$/i.test(token)) {
            const value = this.constant(token, line);
            if (value > 65535) throw new PicaxeCompileError(`number too big: ${token}`, line);
            return '1' + picaxeNumber(value);
        }
        return '0' + picaxeBits(this.variable(token, line), 8);
    }

    // simulator operand: { k: constant } or a variable slot
    ref(token, line) {
        if (/^(\d+|%[01]+|\$[0-9a-f]+)$/i.test(token)) {
            const value = this.constant(token, line);
            if (value > 65535) throw new PicaxeCompileError(`number too big: ${token}`, line);
            return { k: value };
        }
        return this.slot(token, line);
    }

    pinRef(token, line) {
        const m = token.toUpperCase().match(/^([ABC])\.([0-7])$/);
        return m ? { k: PICAXE_COMPILER.PORTS[m[1]] + +m[2] } : this.ref(token, line);
    }

    pin(token, line) {
        const m = token.toUpperCase().match(/^([ABC])\.([0-7])$/);
        if (!m) return this.operand(token, line);
        return '1' + picaxeNumber(PICAXE_COMPILER.PORTS[m[1]] + +m[2]);
    }

    // ---------- statements

    // lead: first bit of the opcode, written before the body (in the header for the first statement)
    // op: instruction for the simulator (see program())
    emit(line, bits, lead = false, op = null) {
        this.items.push({ line, lead, bits: typeof bits === 'function' ? bits : () => bits, op });
    }

    emitGoto(line, label) {
        this.emit(line, this.jump('11001', label), false, { op: 'goto', target: label });
    }

    label(name) {
        this.items.push({ label: name.toLowerCase() });
    }

    newLabel() {
        return `%${this.labelCount++}`;
    }

    jump(opcode, label) {
        return (addresses) => opcode + picaxeBits(this.address(addresses, label), 15);
    }

    address(addresses, label) {
        if (!(label in addresses)) throw new PicaxeCompileError(`unknown label ${label}`);
        return addresses[label];
    }

    // [lhs op rhs] [and|or lhs op rhs]...: emits the jumps to `label` when the condition is false (mode 'false', 'if')
    // or true (mode 'true'). Chained comparisons: jump code | 16 before and, | 24 before or.
    // 'false' (do while, elseif): one if, jump-when-false codes with and/or swapped (De Morgan)
    // 'if' (if ... then, several comparisons): if jumping to the body when true, then goto `label`
    branch(text, label, line, mode = 'false') {
        const parts = text.trim().split(/\s+(and|or)\s+/i);
        const conditions = [];
        for (let i = 0; i < parts.length; i += 2) {
            const m = parts[i].match(/^(\S+)\s*(<>|<=|>=|=|<|>)\s*(\S+)$/);
            if (!m) throw new PicaxeCompileError(`unsupported condition: ${parts[i]}`, line);
            if (this.isNumber(m[1])) throw new PicaxeCompileError(`the left side of a comparison must be a variable: ${parts[i]}`, line);
            const link = (parts[i + 1] || '').toLowerCase();
            conditions.push({ lhs: m[1], op: m[2], rhs: m[3], link });
        }
        const { CMP_FALSE, NEGATE } = PICAXE_COMPILER;
        const conds = conditions.map(c => ({ lhs: this.slot(c.lhs, line), cmp: c.op, rhs: this.ref(c.rhs, line), link: c.link }));
        if (mode === 'if' && conditions.length === 1) mode = 'false';
        const head = '11000' + conditions.map(({ lhs, op, rhs, link }) => {
            const code = mode === 'false' ? CMP_FALSE[op] : CMP_FALSE[NEGATE[op]];
            const and = mode === 'false' ? 24 : 16, or = mode === 'false' ? 16 : 24;
            const chain = link === 'and' ? and : link === 'or' ? or : 0;
            return this.operand(rhs, line) + picaxeBits(this.variable(lhs, line), 8) + picaxeBits(code | chain, 5);
        }).join('');
        if (mode !== 'if') return this.emit(line, (addresses) => head + picaxeBits(this.address(addresses, label), 15), false, { op: 'if', conds, jumpIf: mode === 'true', target: label });
        const body = this.newLabel();
        this.emit(line, (addresses) => head + picaxeBits(this.address(addresses, body), 15), false, { op: 'if', conds, jumpIf: true, target: body });
        this.emitGoto(line, label);
        this.label(body);
    }

    expression(dst, text, line) {
        const tokens = text.trim().split(/\s*(\/\/|[-+*/&|])\s*/);
        const operands = tokens.filter((_, i) => i % 2 === 0), ops = tokens.filter((_, i) => i % 2 === 1);
        if (operands.some(o => !o)) throw new PicaxeCompileError(`unsupported expression: ${text}`, line);
        const dstCode = picaxeBits(this.variable(dst, line), 8);
        if (!ops.length) return ['01010' + this.operand(operands[0], line) + dstCode, this.letOp(dst, operands, ops, line)];
        const opBits = (i) => picaxeBits(PICAXE_COMPILER.OPS[ops[i]], 5) + (i < ops.length - 1 ? '1' : '0');
        // in place (let a = a + ...): the first operand is the destination itself
        const inPlace = !this.isNumber(operands[0]) && this.variable(operands[0], line) === this.variable(dst, line);
        let bits = inPlace
            ? '10101' + this.operand(operands[1], line) + dstCode + opBits(0)
            : '10101' + this.operand(operands[0], line) + dstCode + '000011' + this.operand(operands[1], line) + opBits(0);
        for (let i = 1; i < ops.length; i++) bits += this.operand(operands[i + 1], line) + opBits(i);
        return [bits, this.letOp(dst, operands, ops, line)];
    }

    letOp(dst, operands, ops, line) {
        return { op: 'let', dst: this.slot(dst, line), terms: operands.map(o => this.ref(o, line)), ops };
    }

    // "AB", 13, w0 -> ['65', '66', '13', 'w0'] (# kept: #w0)
    values(args, line) {
        const values = [];
        for (const arg of args.match(/"[^"]*"|[^,]+/g) || []) {
            const a = arg.trim();
            if (a.startsWith('"')) [...a.slice(1, -1)].forEach(c => values.push(String(c.charCodeAt(0) & 0xff)));
            else values.push(a);
        }
        if (!values.length) throw new PicaxeCompileError('no data', line);
        return values;
    }

    sertxd(args, line) {
        const items = this.values(args, line).map(v => v.startsWith('#') ? [v.slice(1).trim(), true] : [v, false]);
        const bits = PICAXE_COMPILER.SERTXD + items.map(([v, hash], i) => this.operand(v, line) + (hash ? '1' : '0') + (i < items.length - 1 ? '1' : '0')).join('');
        return [bits, { op: 'sertxd', items: items.map(([v, dec]) => ({ v: this.ref(v, line), dec })) }];
    }

    line(text, n) {
        if (this.inRem) {
            if (/^\s*#endrem\b/i.test(text)) this.inRem = false;
            return;
        }
        // a comment starts at ' or ; outside a "string"
        text = text.replace(/^((?:[^"';]|"[^"]*")*)[';].*$/, '$1').trim();
        if (!text) return;
        let m;
        if (/^#rem\b/i.test(text)) return void (this.inRem = true);
        if ((m = text.match(/^#picaxe\s+(\S+)$/i))) {
            if (!PICAXE_COMPILER.CHIPS.includes(m[1].toUpperCase())) throw new PicaxeCompileError(`PICAXE ${m[1]} not supported yet`, n);
            return;
        }
        if ((m = text.match(/^symbol\s+(\w+)\s*=\s*(\w+)$/i))) return void (this.symbols[m[1].toLowerCase()] = m[2].toLowerCase());
        if ((m = text.match(/^(\w+):$/))) return this.label(m[1]);
        const [, word, args] = text.match(/^(\w+)\s*(.*)$/) || [, text, ''];
        const list = () => args.split(',').map(a => a.trim());
        switch (word.toLowerCase()) {
            case 'high': return this.emit(n, '00000' + this.pin(args, n), false, { op: 'high', pin: this.pinRef(args, n) });
            case 'low': return this.emit(n, '00001' + this.pin(args, n), false, { op: 'low', pin: this.pinRef(args, n) });
            case 'toggle': return this.emit(n, '00100' + this.pin(args, n), false, { op: 'toggle', pin: this.pinRef(args, n) });
            case 'pause': return this.emit(n, '01111' + this.operand(args, n), false, { op: 'pause', ms: this.ref(args, n) });
            case 'end': return this.emit(n, '111110', true, { op: 'end' });
            case 'return': return this.emit(n, '11011', false, { op: 'return' });
            case 'goto': return this.emitGoto(n, args.toLowerCase());
            case 'gosub': {
                const index = ++this.gosubs;
                if (index > 255) throw new PicaxeCompileError('too many gosub', n);
                const jump = this.jump('01110' + picaxeBits(index, 8), args.toLowerCase());
                const back = this.newLabel();
                this.emit(n, jump, false, { op: 'gosub', target: args.toLowerCase() });
                this.label(back);
                return void (this.gosubReturns = [...(this.gosubReturns || []), back]);
            }
            case 'readadc':
            case 'readadc10': {
                const [pin, variable] = list();
                if (!(pin.toUpperCase() in PICAXE_COMPILER.ADC)) throw new PicaxeCompileError(`${pin} has no ADC channel`, n);
                const ten = word.toLowerCase() === 'readadc10';
                const bits = '00111' + '1' + picaxeNumber(PICAXE_COMPILER.ADC[pin.toUpperCase()]) + (ten ? '1' : '0') + picaxeBits(this.variable(variable, n), 8);
                const [, port, bit] = pin.toUpperCase().match(/^([ABC])\.([0-7])$/);
                return this.emit(n, bits, false, { op: 'readadc', pin: PICAXE_COMPILER.PORTS[port] + +bit, ten, dst: this.slot(variable, n) });
            }
            case 'servo': {
                const [pin, position] = list();
                return this.emit(n, '10111' + this.pin(pin, n) + this.operand(position, n) + '00', true, { op: 'servo', pin: this.pinRef(pin, n), pos: this.ref(position, n) });
            }
            case 'sound': {
                m = args.match(/^(\S+?)\s*,\s*\(\s*(\S+?)\s*,\s*(\S+?)\s*\)$/);
                if (!m) throw new PicaxeCompileError('sound pin, (note, duration) expected', n);
                return this.emit(n, '10010' + this.pin(m[1], n) + this.operand(m[3], n) + this.operand(m[2], n) + '0', false,
                    { op: 'sound', pin: this.pinRef(m[1], n), note: this.ref(m[2], n), duration: this.ref(m[3], n) });
            }
            case 'hi2csetup': {
                if (!(m = args.match(/^i2cmaster\s*,\s*(\S+)\s*,\s*(i2cslow|i2cfast)\s*,\s*(i2cbyte|i2cword)$/i))) throw new PicaxeCompileError('hi2csetup i2cmaster, address, i2cslow|i2cfast, i2cbyte|i2cword expected', n);
                const speed = { i2cslow: '00011010010011100', i2cfast: '0001010100100' }[m[2].toLowerCase()];
                return this.emit(n, '111111' + picaxeNumber(this.constant(m[1], n)) + speed + (m[3].toLowerCase() === 'i2cword' ? '1' : '0'), false, { op: 'hi2csetup', address: this.constant(m[1], n) });
            }
            case 'hi2cout': {
                if (!(m = args.match(/^(?:\[(\S+?)\]\s*,\s*)?(?:(\S+?)\s*,\s*)?\((.*)\)$/))) throw new PicaxeCompileError('hi2cout [address], register, (data) expected', n);
                const items = [...(m[2] ? [m[2]] : []), ...this.values(m[3], n)];
                const address = m[1] ? '1' + this.operand(String(this.constant(m[1], n)), n) : '0';
                return this.emit(n, '10000' + address + items.map((v, i) => this.operand(v, n) + (i < items.length - 1 ? '1' : '0')).join(''), true,
                    { op: 'hi2cout', address: m[1] ? this.constant(m[1], n) : null, data: items.map(v => this.ref(v, n)) });
            }
            case 'sertxd': {
                if (!(m = args.match(/^\((.*)\)$/))) throw new PicaxeCompileError('sertxd(...) expected', n);
                const [bits, op] = this.sertxd(m[1], n);
                return this.emit(n, bits, false, op);
            }
            case 'let': {
                if (!(m = args.match(/^(\S+)\s*=\s*(.+)$/))) throw new PicaxeCompileError('let variable = value expected', n);
                const [bits, op] = this.expression(m[1], m[2], n);
                return this.emit(n, bits, false, op);
            }
            case 'if': {
                if (!(m = args.match(/^(.+?)\s+then$/i))) throw new PicaxeCompileError('if ... then expected', n);
                const block = { type: 'if', next: this.newLabel(), end: this.newLabel() };
                this.blocks.push(block);
                return this.branch(m[1], block.next, n, 'if');
            }
            case 'elseif':
            case 'else': {
                const block = this.blocks.at(-1);
                if (!block || block.type !== 'if' || !block.next) throw new PicaxeCompileError(`${word} without if`, n);
                this.emitGoto(n, block.end);
                this.label(block.next);
                block.next = null;
                if (word.toLowerCase() === 'else') return;
                if (!(m = args.match(/^(.+?)\s+then$/i))) throw new PicaxeCompileError('elseif ... then expected', n);
                block.next = this.newLabel();
                return this.branch(m[1], block.next, n);
            }
            case 'endif': {
                const block = this.blocks.pop();
                if (!block || block.type !== 'if') throw new PicaxeCompileError('endif without if', n);
                if (block.next) this.label(block.next);
                return this.label(block.end);
            }
            case 'do': {
                const block = { type: 'do', top: this.newLabel(), end: this.newLabel() };
                this.blocks.push(block);
                this.label(block.top);
                if (!args) return;
                if (!(m = args.match(/^(while|until)\s+(.+)$/i))) throw new PicaxeCompileError('do [while|until condition] expected', n);
                return this.branch(m[2], block.end, n, m[1].toLowerCase() === 'until' ? 'true' : 'false');
            }
            case 'loop': {
                const block = this.blocks.pop();
                if (!block || block.type !== 'do') throw new PicaxeCompileError('loop without do', n);
                if (args) throw new PicaxeCompileError('loop while/until is not supported', n);
                this.emitGoto(n, block.top);
                return this.label(block.end);
            }
            case 'for': {
                if (!(m = args.match(/^(\S+)\s*=\s*(\S+)\s+to\s+(\S+)(?:\s+step\s+(\S+))?$/i))) throw new PicaxeCompileError('for variable = start to end [step n] expected', n);
                const block = { type: 'for', variable: m[1], start: m[2], limit: m[3], step: m[4] || '1', top: this.newLabel() };
                this.blocks.push(block);
                const [bits, op] = this.expression(m[1], m[2], n);
                this.emit(n, bits, false, op);
                return this.label(block.top);
            }
            case 'next': {
                const block = this.blocks.pop();
                if (!block || block.type !== 'for') throw new PicaxeCompileError('next without for', n);
                const head = '10111' + this.operand(block.step, n) + picaxeBits(this.variable(block.variable, n), 8) + '1' + this.operand(block.limit, n) + this.operand(block.start, n);
                return this.emit(n, this.jump(head, block.top), false,
                    { op: 'next', v: this.slot(block.variable, n), step: this.ref(block.step, n), limit: this.ref(block.limit, n), target: block.top });
            }
        }
        throw new PicaxeCompileError(`unsupported instruction: ${text}`, n);
    }

    // instructions for picaxeMachine.js: { code: [{ op, ..., line }], variables: [{ name, register, slot }] }, jump targets = indexes in code
    static program(source) {
        const c = new PicaxeCompiler(source);
        c.compile();
        const code = [], labels = Object.create(null);
        for (const item of c.items) item.label ? labels[item.label] = code.length : code.push({ ...item.op, line: item.line });
        code.forEach(i => { if ('target' in i) i.target = labels[i.target]; });
        const variables = Object.entries(c.symbols).filter(([, r]) => /^[bw]\d+$/.test(r)).map(([name, r]) => ({ name, register: r, slot: c.slot(r) }));
        return { code, variables };
    }

    // ---------- layout

    link() {
        const statements = this.items.filter(item => item.bits);
        // pass 1: positions (bit lengths do not depend on addresses)
        const addresses = Object.create(null), pending = [];
        let position = 23; // absolute bit of the class bit of the next statement
        for (const item of this.items) {
            if (item.label) { pending.push(item.label); continue; }
            pending.splice(0).forEach(label => addresses[label] = position);
            item.position = position;
            position += 1 + item.bits(new Proxy({}, { get: () => 0, has: () => true })).length;
        }
        pending.forEach(label => addresses[label] = position); // labels at the end: the terminator
        // pass 2: stream
        let stream = '';
        statements.forEach((item, i) => {
            if (i > 0) stream += item.lead ? '1' : '0';
            stream += item.bits(addresses);
        });
        const firstClass = statements.length ? (statements[0].lead ? 1 : 0) : 1;
        if (statements.length) stream += '1';
        stream += '11111';
        const header = ((24 + stream.length + 1) << 1) | firstClass;
        let bits = picaxeBits(header, 24) + stream;
        if (this.gosubs) bits += '0'.repeat(16) + (this.gosubReturns || []).map(label => picaxeBits(addresses[label], 15)).join('');
        if (bits.length > PICAXE_COMPILER.PROGRAM_SIZE * 8) throw new PicaxeCompileError('program too big for the PICAXE memory');
        const obj = new Uint8Array(PICAXE_COMPILER.OBJ_SIZE);
        for (let i = 0; i < bits.length; i += 8) obj[i / 8] = parseInt(bits.slice(i, i + 8).padEnd(8, '0'), 2);
        return { obj, eee: new Uint8Array(PICAXE_COMPILER.EEPROM_SIZE), used: Math.ceil(bits.length / 8) };
    }
}

if (typeof module !== 'undefined') {
    module.exports = { PICAXE_COMPILER, PicaxeCompiler, PicaxeCompileError, picaxeNumber };
}
